    (4003, 9030, 'Bộ công cụ theo dõi chi phí hạ tầng', 'Gom hoá đơn từ nhiều nhà cung cấp về một bảng, cảnh báo khi vượt ngưỡng.', NULL, 'OPEN', '["Developer Experience","API Design","Web Performance"]'::jsonb, now() - INTERVAL '256 days', now() - INTERVAL '256 days'),
    (4004, 9043, 'Hệ thống gợi ý bài viết', 'Xếp hạng nội dung theo hành vi đọc thật thay vì theo thời gian đăng.', NULL, 'OPEN', '["Observability","Infrastructure as Code","Cost Optimization"]'::jsonb, now() - INTERVAL '285 days', now() - INTERVAL '285 days'),
    (4005, 9057, 'Ứng dụng ghi chú offline-first', 'Ghi được khi mất mạng, đồng bộ lại khi có mạng mà không mất dữ liệu.', NULL, 'OPEN', '["Product Discovery","User Research"]'::jsonb, now() - INTERVAL '19 days', now() - INTERVAL '19 days'),
