    (4007, 9084, 'Khung kiểm thử tự động dùng chung', 'Bộ khung để các đội viết test tích hợp mà không dựng lại hạ tầng.', NULL, 'OPEN', '["AppSec","Threat Modeling"]'::jsonb, now() - INTERVAL '200 days', now() - INTERVAL '200 days'),
